            <div class="macro-bar-item">
              <div class="macro-bar-row">
                <span class="macro-bar-label">Glucides</span>
                <span class="macro-bar-val">{{ format1(recipe?.totals?.carbs) }}&thinsp;g</span>
              </div>
              <div class="macro-bar-track">
                <div class="macro-bar-fill macro-bar-fill--carbs" :style="{ width: macroBarWidth('carbs') }" />
              </div>
            </div>
            <div class="macro-bar-item">
              <div class="macro-bar-row">
                <span class="macro-bar-label">Lipides</span>
                <span class="macro-bar-val">{{ format1(recipe?.totals?.fat) }}&thinsp;g</span>
