          <!-- Nova warning -->
          <div v-if="novaWarning" class="recipe-warning" :class="'recipe-warning--' + novaWarning.type">
            <v-icon size="14" class="mr-1">{{ novaWarning.icon }}</v-icon>
            <span>{{ novaWarning.message }}</span>
          </div>

          <!-- Actions -->
          <div class="hero-actions">
            <button class="action-btn action-btn--cart" @click="createShoppingListFromRecipe()">
              <v-icon size="15" class="mr-1">mdi-cart-plus</v-icon>
              Liste de courses
            </button>
            <div class="action-icons">
              <button
                v-if="!recipe?.baseRecipe && !isFromBaseCatalog"
                class="hero-btn hero-btn--icon"
                :class="{ 'hero-btn--icon-active': recipe?.favorite }"
                @click="toggleFavorite()"
                title="Favori"
              >
                <v-icon size="17">{{ recipe?.favorite ? 'mdi-star' : 'mdi-star-outline' }}</v-icon>
              </button>
              <button v-if="canEditBaseRecipe" class="hero-btn hero-btn--icon" @click="editRecipe()" title="Modifier">
                <v-icon size="17">mdi-pencil-outline</v-icon>
              </button>
              <button v-if="canEditBaseRecipe" class="hero-btn hero-btn--icon hero-btn--danger" @click="requestDelete" title="Supprimer">
                <v-icon size="17">mdi-delete-outline</v-icon>
              </button>
            </div>
          </div>
        </div>
      </div><!-- /hero-layout -->

      <!-- ── INGRÉDIENTS ── -->
      <div class="section-block">
        <p class="section-title">
          Ingrédients
          <span v-if="recipe?.ingredients?.length" class="section-count">{{ recipe.ingredients.length }}</span>
        </p>

        <div v-if="!recipe?.ingredients?.length" class="recipe-empty">
          <v-icon size="28" style="opacity:.3">mdi-food-off</v-icon>
          <span>Aucun ingrédient</span>
        </div>

        <!-- Grille bulles ingrédients -->
        <div v-else class="ing-bubbles">
          <div
            v-for="(ing, i) in recipe.ingredients"
            :key="i"
            class="ing-bubble"
            :class="{ 'ing-bubble--clickable': ing.productImage || ing.availableStores?.length || ing.productLink }"
