          >
            <div class="ing-bubble__circle">
              <img v-if="ing.productImage" :src="ing.productImage" class="ing-bubble__img" :alt="ing.name" />
              <div v-else class="ing-bubble__placeholder">
                <v-icon size="26" style="opacity:.3">mdi-food-variant</v-icon>
              </div>
              <div class="ing-card__badges">
                <span
                  v-if="getNovaDisplay(ing.novaGroup)"
                  class="ing-micro-badge"
                  :style="{ background: getNovaDisplay(ing.novaGroup).color }"
                >N{{ getNovaNumber(ing.novaGroup) }}</span>
                <span
                  v-if="ing.nutriscore"
                  class="ing-micro-badge"
                  :style="{ background: nutriscoreBg(ing.nutriscore) }"
                >{{ ing.nutriscore }}</span>
              </div>
              <!-- Crayon admin -->
              <button
                v-if="isAdmin"
                class="ing-bubble__edit"
                @click.stop="openIngredientEdit(ing)"
                title="Modifier l'ingrédient"
              >
                <v-icon size="12">mdi-pencil</v-icon>
              </button>
            </div>
            <span class="ing-bubble__name">{{ ing.name || ing.productName }}</span>
            <span class="ing-bubble__qty">{{ ing.grams }}&thinsp;g</span>
          </div>
        </div>
      </div>

      <!-- ── PRÉPARATION (Étapes) ── -->
      <div v-if="recipe?.steps?.length" class="section-block">
        <p class="section-title">Préparation</p>
        <div class="steps-list">
          <div v-for="(step, i) in recipe.steps" :key="i" class="step-item">
            <div class="step-number">{{ i + 1 }}</div>
            <div class="step-content detail-text" v-html="step" />
