    </div><!-- /recipe-centered -->

    <!-- ─── Dialog suppression ─── -->
    <v-dialog v-model="askDelete" max-width="400">
      <v-card rounded="xl" color="secondary">
        <v-card-title class="pt-5 px-5 text-body-1 font-weight-bold detail-text">Supprimer la recette ?</v-card-title>
