        <v-card-actions class="px-5 pb-5">
          <v-spacer />
          <button class="dialog-btn dialog-btn--cancel" @click="askDelete = false">Annuler</button>
          <button class="dialog-btn dialog-btn--delete" @click="deleteRecipe">Supprimer</button>
