      </v-card>
    </v-dialog>

    <!-- ─── Dialog détail ingrédient ─── -->
    <v-dialog v-model="ingredientDetailDialog.open" max-width="500" scrollable>
      <v-card v-if="ingredientDetailDialog.ing" rounded="xl" color="secondary">
        <div class="ing-detail-header">
          <div class="ing-detail-img-wrap">
            <img v-if="ingredientDetailDialog.ing.productImage" :src="ingredientDetailDialog.ing.productImage" class="ing-detail-img" />
            <div v-else class="ing-detail-img-placeholder">
              <v-icon size="28" style="opacity:.35">mdi-food-variant</v-icon>
            </div>
          </div>
          <div class="ing-detail-info">
            <p class="ing-detail-name">{{ ingredientDetailDialog.ing.name || ingredientDetailDialog.ing.productName }}</p>
            <p v-if="ingredientDetailDialog.ing.productBrand" class="ing-detail-brand">{{ ingredientDetailDialog.ing.productBrand }}</p>
            <div class="ing-detail-badges">
              <span v-if="getNovaDisplay(ingredientDetailDialog.ing.novaGroup)" class="ing-micro-badge" :style="{ background: getNovaDisplay(ingredientDetailDialog.ing.novaGroup).color }">
                Nova {{ getNovaNumber(ingredientDetailDialog.ing.novaGroup) }}
              </span>
              <span v-if="ingredientDetailDialog.ing.nutriscore" class="ing-micro-badge" :style="{ background: nutriscoreBg(ingredientDetailDialog.ing.nutriscore) }">
                {{ ingredientDetailDialog.ing.nutriscore }}
              </span>
            </div>
          </div>
          <button class="ing-detail-close" @click="ingredientDetailDialog.open = false">
            <v-icon size="18">mdi-close</v-icon>
          </button>
        </div>
        <v-card-text class="px-5 pt-3 pb-5">
          <a v-if="ingredientDetailDialog.ing.productLink" :href="ingredientDetailDialog.ing.productLink" target="_blank" rel="noopener noreferrer" class="ing-product-link">
            <v-icon size="13" class="mr-1">mdi-open-in-new</v-icon>
            Voir la page produit
          </a>
          <div v-if="ingredientDetailDialog.ing.nutriments_map?.length" class="mt-4">
            <p class="section-title mb-2" style="font-size:11px">Valeurs / 100 g</p>
            <div class="nutr-table">
              <div v-for="n in ingredientDetailDialog.ing.nutriments_map" :key="n.key" class="nutr-table-row">
                <span class="detail-text">{{ nutrimentLabel(n.key) }}</span>
                <strong class="detail-text">{{ n.value }}</strong>
              </div>
            </div>
          </div>
          <div v-if="ingredientDetailDialog.ing.availableStores?.length" class="mt-4">
            <p class="section-title mb-2" style="font-size:11px">Disponible dans</p>
            <div class="d-flex flex-wrap gap-2">
              <span v-for="store in ingredientDetailDialog.ing.availableStores" :key="store" class="store-pill">
                <v-icon size="12" class="mr-1">mdi-store-outline</v-icon>{{ store }}
              </span>
            </div>
          </div>
        </v-card-text>
      </v-card>
    </v-dialog>

    <!-- ─── Dialog édition ingrédient (admin) ─── -->
    <v-dialog v-model="ingEditDialog" max-width="540" scrollable>
      <v-card rounded="xl" color="secondary">

        <!-- Header -->
        <div class="ied-header">
          <div class="ied-header__info">
            <p class="ied-header__label">Modifier l'ingrédient</p>
            <p class="ied-header__name">{{ ingEditForm.productName || 'Sans nom' }}</p>
          </div>
          <button class="ing-detail-close" @click="ingEditDialog = false">
            <v-icon size="18">mdi-close</v-icon>
          </button>
        </div>

        <v-card-text class="ied-body">

          <!-- Aperçu image -->
          <div class="ied-img-preview">
            <div class="ied-img-wrap">
              <img v-if="ingEditForm.productImage" :src="ingEditForm.productImage" class="ied-img" />
              <div v-else class="ied-img-placeholder">
                <v-icon size="30" style="opacity:.25">mdi-image-outline</v-icon>
              </div>
            </div>
            <div class="ied-img-field">
              <label class="ied-label">URL de l'image</label>
              <input v-model="ingEditForm.productImage" class="ied-input" placeholder="https://..." />
            </div>
          </div>

          <!-- Identité -->
          <div class="ied-section">
            <p class="ied-section-title">Identité</p>
            <div class="ied-grid-2">
              <div class="ied-field">
                <label class="ied-label">Nom du produit</label>
                <input v-model="ingEditForm.productName" class="ied-input" />
              </div>
              <div class="ied-field">
                <label class="ied-label">Marque</label>
                <input v-model="ingEditForm.productBrand" class="ied-input" placeholder="Facultatif" />
              </div>
            </div>
            <div class="ied-field mt-2">
              <label class="ied-label">Lien produit</label>
              <input v-model="ingEditForm.productLink" class="ied-input" placeholder="https://..." />
            </div>
          </div>

          <!-- Qualité -->
          <div class="ied-section">
            <p class="ied-section-title">Qualité</p>
            <div class="ied-grid-2">
              <div class="ied-field">
                <label class="ied-label">Nutriscore</label>
                <div class="ied-radio-row">
                  <button
                    v-for="s in NUTRISCORE_OPTIONS" :key="s"
                    class="ied-score-btn"
                    :class="{ 'ied-score-btn--active': ingEditForm.nutriscore === s }"
                    :style="ingEditForm.nutriscore === s ? { background: nutriscoreBg(s), color: '#fff', borderColor: nutriscoreBg(s) } : {}"
                    @click="ingEditForm.nutriscore = ingEditForm.nutriscore === s ? '' : s"
                  >{{ s }}</button>
                </div>
              </div>
              <div class="ied-field">
                <label class="ied-label">Nova</label>
                <div class="ied-radio-col">
                  <button
                    v-for="opt in NOVA_OPTIONS" :key="opt.value"
                    class="ied-nova-btn"
                    :class="{ 'ied-nova-btn--active': ingEditForm.novaGroup === opt.value }"
                    @click="ingEditForm.novaGroup = ingEditForm.novaGroup === opt.value ? '' : opt.value"
                  >
                    <span class="ied-nova-dot" :style="{ background: ['#2d9a4e','#c8b400','#e07020','#e63946'][opt.value - 1] }" />
                    {{ opt.label }}
                  </button>
                </div>
              </div>
            </div>
          </div>

          <!-- Valeurs nutritionnelles / 100g -->
          <div class="ied-section">
            <p class="ied-section-title">Valeurs nutritionnelles <span class="ied-section-sub">/ 100 g</span></p>
            <div class="ied-grid-3">
              <div class="ied-field">
                <label class="ied-label">Calories (kcal)</label>
                <input v-model="ingEditForm.kcal" class="ied-input" type="number" min="0" />
              </div>
              <div class="ied-field">
                <label class="ied-label">Protéines (g)</label>
                <input v-model="ingEditForm.protein" class="ied-input" type="number" min="0" step="0.1" />
              </div>
              <div class="ied-field">
                <label class="ied-label">Glucides (g)</label>
                <input v-model="ingEditForm.carbs" class="ied-input" type="number" min="0" step="0.1" />
              </div>
              <div class="ied-field">
                <label class="ied-label">Lipides (g)</label>
                <input v-model="ingEditForm.fat" class="ied-input" type="number" min="0" step="0.1" />
              </div>
              <div class="ied-field">
                <label class="ied-label">Fibres (g)</label>
                <input v-model="ingEditForm.fiber" class="ied-input" type="number" min="0" step="0.1" />
              </div>
            </div>
          </div>

          <!-- Magasins -->
          <div class="ied-section">
            <p class="ied-section-title">Disponible dans</p>
            <div class="ied-store-pills">
              <button
                v-for="store in STORES_OPTIONS" :key="store"
                class="ied-store-pill"
                :class="{ 'ied-store-pill--active': ingEditForm.availableStores?.includes(store) }"
                @click="toggleStore(store)"
              >{{ store }}</button>
            </div>
          </div>

        </v-card-text>

        <!-- Footer -->
        <div class="ied-footer">
          <button class="dialog-btn dialog-btn--cancel" @click="ingEditDialog = false">Annuler</button>
          <button class="dialog-btn dialog-btn--save" :disabled="ingEditSaving" @click="saveIngredientEdit">
            <v-progress-circular v-if="ingEditSaving" indeterminate size="14" width="2" class="mr-1" />
            Enregistrer
          </button>
        </div>
      </v-card>
    </v-dialog>

    <v-snackbar v-model="snack.show" :timeout="2500" rounded="pill">{{ snack.text }}</v-snackbar>
    <v-alert v-if="errorMessage" type="error" variant="tonal" class="mt-4 mx-4">{{ errorMessage }}</v-alert>
  </div>
</template>

<script setup>
  import { ref, computed, onMounted, watch } from 'vue'
  import { useRouter, useRoute } from 'vue-router'
  import { useAuthStore } from '@/store/auth_store'
  import { getUserRecipeById, deleteRecipeFromUserCollection, setRecipeAsFavorite } from '@/service/recipe_service'
  import { getBaseRecipeById, deleteBaseRecipe } from '@/service/base_recipe_service'
  import { getIngredientsByBarcodes, getNovaStringAndColor, updateProduct } from '@/service/ingredient_service'
  import { addShoppingList, getUserShoppingLists } from '@/service/shopping_list_service'
  import TopDeck from '@/components/Utils/TopDeck.vue'

  const props = defineProps({ id: { type: String, required: true } })
  const router = useRouter()
  const route = useRoute()
  const authStore = useAuthStore()
  const recipe = ref(null)
  const isLoading = ref(false)
  const errorMessage = ref('')
  const snack = ref({ show: false, text: '' })
  const askDelete = ref(false)

  const ingredientDetailDialog = ref({ open: false, ing: null })
  function openIngredientDetail(ing) {
    ingredientDetailDialog.value = { open: true, ing }
  }

  // ── Édition ingrédient (admin) ──
  const ingEditDialog = ref(false)
  const ingEditSaving = ref(false)
  const ingEditForm = ref({})
  const NOVA_OPTIONS = [
    { value: 1, label: 'Nova 1 — Non transformé' },
    { value: 2, label: 'Nova 2 — Ingrédient culinaire' },
    { value: 3, label: 'Nova 3 — Transformé' },
    { value: 4, label: 'Nova 4 — Ultra-transformé' },
  ]
  const NUTRISCORE_OPTIONS = ['A', 'B', 'C', 'D', 'E']
  const STORES_OPTIONS = ['Carrefour', 'Leclerc', 'Lidl', 'Aldi', 'Intermarché', 'Super U', 'Monoprix', 'Biocoop', 'Casino', 'Autre']

  function openIngredientEdit(ing) {
    ingEditForm.value = {
      id: ing.id,
      productName: ing.productName || ing.name || '',
      productBrand: ing.productBrand || '',
      productImage: ing.productImage || '',
      productLink: ing.productLink || '',
      nutriscore: ing.nutriscore || '',
      novaGroup: getNovaNumber(ing.novaGroup) ?? '',
      availableStores: [...(ing.availableStores || [])],
      // nutriments editables
      kcal: ing.nutritionPer100g?.kcal ?? '',
      protein: ing.nutritionPer100g?.protein ?? '',
      carbs: ing.nutritionPer100g?.carbs ?? '',
      fat: ing.nutritionPer100g?.fat ?? '',
      fiber: ing.nutritionPer100g?.fiber ?? '',
    }
    ingEditDialog.value = true
  }

  async function saveIngredientEdit() {
    if (!authStore.userid || !ingEditForm.value.id) return
    ingEditSaving.value = true
    try {
      const f = ingEditForm.value
      const payload = {
        productName: f.productName,
        productBrand: f.productBrand,
        productImage: f.productImage,
        productLink: f.productLink,
        nutriscore: f.nutriscore || null,
        novaGroup: f.novaGroup !== '' ? Number(f.novaGroup) : null,
        availableStores: f.availableStores,
        nutritionPer100g: {
          kcal: f.kcal !== '' ? Number(f.kcal) : null,
          protein: f.protein !== '' ? Number(f.protein) : null,
          carbs: f.carbs !== '' ? Number(f.carbs) : null,
          fat: f.fat !== '' ? Number(f.fat) : null,
          fiber: f.fiber !== '' ? Number(f.fiber) : null,
        },
      }
      await updateProduct(authStore.userid, { [f.id]: payload })
      // Mise à jour locale immédiate dans recipe.ingredients
      const idx = recipe.value.ingredients.findIndex(i => i.id === f.id)
      if (idx !== -1) {
        recipe.value.ingredients[idx] = {
          ...recipe.value.ingredients[idx],
          productName: f.productName,
          name: f.productName,
          productBrand: f.productBrand,
          productImage: f.productImage,
          productLink: f.productLink,
          nutriscore: f.nutriscore,
          novaGroup: f.novaGroup !== '' ? Number(f.novaGroup) : null,
          availableStores: f.availableStores,
          nutritionPer100g: payload.nutritionPer100g,
        }
      }
      ingEditDialog.value = false
      snack.value = { show: true, text: 'Ingrédient mis à jour ✓' }
    } catch (e) {
      console.error(e)
      snack.value = { show: true, text: 'Erreur lors de la sauvegarde.' }
    } finally {
      ingEditSaving.value = false
    }
  }

  function nutriscoreBg(v) {
    const map = { A: '#2d9a4e', B: '#78c240', C: '#f5c518', D: '#f07823', E: '#e63946' }
    return map[v?.toUpperCase()] || '#9E9E9E'
  }

  const NUTRIMENT_LABELS = {
    'energy-kcal': 'Énergie (kcal)', 'fat': 'Lipides', 'saturated-fat': 'dont AG saturés',
    'carbohydrates': 'Glucides', 'sugar': 'dont Sucres', 'sugars': 'dont Sucres',
    'proteins': 'Protéines', 'fiber': 'Fibres', 'salt': 'Sel',
  }
  function nutrimentLabel(key) { return NUTRIMENT_LABELS[key] || key }

  const isAdmin = computed(() => authStore.userInfos?.role === 'admin')
  const isFromBaseCatalog = computed(() => route.query?.source === 'base')
  const canEditBaseRecipe = computed(() => {
    if (!recipe.value) return false
    if (isFromBaseCatalog.value) return isAdmin.value
    return !recipe.value.baseRecipe || isAdmin.value
  })

  const validPreview = ref(true)
  const placeholderImage = 'https://www.mimisrecipes.com/wp-content/uploads/2018/12/recipe-placeholder-featured.jpg'
  const sourceKey = computed(() => recipe.value?.url || recipe.value?.image || recipe.value?.imageUrl || '')
  const previewSrc = computed(() => validPreview.value && sourceKey.value ? sourceKey.value : placeholderImage)
  function onPreviewError() { validPreview.value = false }

  const novaWarning = computed(() => {
    if (!recipe.value?.ingredients?.length) return null
    const novaGroups = recipe.value.ingredients
      .map(ing => {
        const display = getNovaDisplay(ing.novaGroup)
        if (!display) return null
        const match = display.string.match(/\d+/)
        return match ? parseInt(match[0]) : null
      })
      .filter(n => n !== null)
    if (!novaGroups.length) return null
    const hasNova4 = novaGroups.some(n => n === 4)
    const hasNova3 = novaGroups.some(n => n === 3)
    const nova4Count = novaGroups.filter(n => n === 4).length
    const nova3Count = novaGroups.filter(n => n === 3).length
    if (hasNova4) return { type: 'error', icon: 'mdi-alert-circle', message: `Cette recette contient ${nova4Count} ingrédient(s) ultra-transformé(s) (Nova 4). Consommation à limiter.` }
    if (hasNova3 && nova3Count > 1) return { type: 'warning', icon: 'mdi-alert', message: `Cette recette contient ${nova3Count} ingrédients transformés (Nova 3). À consommer avec modération.` }
    return null
  })

  function getNovaDisplay(novaGroup) {
    if (!novaGroup) return null
    let num = null
    if (typeof novaGroup === 'number') { num = novaGroup }
    else if (typeof novaGroup === 'object') {
      if (novaGroup.string) { const m = novaGroup.string.match(/\d+/); num = m ? parseInt(m[0]) : null }
      else if (typeof novaGroup.value === 'number') { num = novaGroup.value }
    } else if (typeof novaGroup === 'string') { const m = novaGroup.match(/\d+/); num = m ? parseInt(m[0]) : null }
    if (!num || num < 1 || num > 4) return null
    return getNovaStringAndColor(num)
  }

  function getNovaNumber(novaGroup) {
    if (!novaGroup) return null
    let num = null
    if (typeof novaGroup === 'number') { num = novaGroup }
    else if (typeof novaGroup === 'object') {
      if (novaGroup.string) { const m = novaGroup.string.match(/\d+/); num = m ? parseInt(m[0]) : null }
      else if (typeof novaGroup.value === 'number') { num = novaGroup.value }
    } else if (typeof novaGroup === 'string') { const m = novaGroup.match(/\d+/); num = m ? parseInt(m[0]) : null }
    return num
  }

  function format1(n) {
    const v = Number(n ?? 0)
    return Number.isFinite(v) ? v.toFixed(1) : '0.0'
  }

  function macroBarWidth(macro) {
    const totals = recipe.value?.totals
    if (!totals) return '0%'
    const protein = Number(totals.protein ?? 0) * 4
    const carbs = Number(totals.carbs ?? 0) * 4
    const fat = Number(totals.fat ?? 0) * 9
    const total = protein + carbs + fat
    if (!total) return '0%'
    const map = { protein, carbs, fat }
    return Math.round((map[macro] / total) * 100) + '%'
  }

  async function loadRecipe() {
    if (!authStore.userid) return
    try {
      isLoading.value = true
      let r = await getUserRecipeById(authStore.userid, props.id)
      if (!r || r.baseRecipe === true) {
        const base = await getBaseRecipeById(props.id)
        if (base) { r = base }
        else if (!r) { errorMessage.value = 'Recette introuvable.'; return }
      }
      const barcodes = r.ingredients?.map(i => i.id) || []
      const fullInfos = await getIngredientsByBarcodes(authStore.userid, barcodes)
      const hydratedIngredients = (r.ingredients || []).map(line => {
        const found = fullInfos.find(f => f.id === line.id)
        return {
          ...line,
          name: line.name || found?.productName || line.id,
          productName: found?.productName || line.name || line.id,
          productBrand: found?.productBrand || '',
          novaGroup: line.novaGroup ?? found?.novaGroup ?? null,
          nutritionPer100g: found?.nutritionPer100g || {},
          productImage: found?.productImage || line.productImage || '',
          nutriscore: found?.nutriscore || line.nutriscore || '',
          availableStores: found?.availableStores || line.availableStores || [],
          productLink: found?.productLink || line.productLink || '',
          nutriments_map: found?.nutriments_map || line.nutriments_map || [],
        }
      })
      recipe.value = { id: props.id, ...r, ingredients: hydratedIngredients }
    } catch (e) {
      console.error(e)
      errorMessage.value = "Erreur lors du chargement de la recette."
    } finally {
      isLoading.value = false
    }
  }

  async function deleteRecipe() {
    if (!canEditBaseRecipe.value) { errorMessage.value = "Action réservée aux administrateurs."; return }
    if (!authStore.userid || !recipe.value?.id) return
    try {
      if (recipe.value?.baseRecipe) { await deleteBaseRecipe(recipe.value.id) }
      else { await deleteRecipeFromUserCollection(authStore.userid, recipe.value.id) }
      askDelete.value = false
      snack.value = { show: true, text: 'Recette supprimée 🗑️' }
      setTimeout(() => router.push('/my_recipes'), 350)
    } catch (e) { console.error(e); errorMessage.value = "Erreur lors de la suppression." }
  }

  async function toggleFavorite() {
    if (!authStore.userid || !recipe.value?.id) return
    try {
      const next = !recipe.value.favorite
      await setRecipeAsFavorite(authStore.userid, recipe.value.id, next)
      recipe.value.favorite = next
      snack.value = { show: true, text: next ? 'Ajoutée aux favoris ⭐' : 'Retirée des favoris' }
    } catch (e) { console.error(e); errorMessage.value = "Erreur lors de la mise à jour du favori." }
  }

  async function createShoppingListFromRecipe() {
    if (!authStore.userid) { errorMessage.value = "Utilisateur non connecté."; return }
    const ingredients = recipe.value?.ingredients || []
    if (!ingredients.length) { errorMessage.value = "Aucun ingrédient à ajouter."; return }
    const items = ingredients
      .map((ing) => {
        const name = String(ing.name || ing.productName || '').trim()
        if (!name) return null
        const grams = Number(ing.grams)
        const quantity = Number.isFinite(grams) && grams > 0 ? `${grams} g` : 1
        return { name, quantity }
      })
      .filter(Boolean)
    if (!items.length) { errorMessage.value = "Aucun ingrédient valide à ajouter."; return }
    const listName = (recipe.value?.title || "Liste de courses").trim()
    try {
      const existingLists = await getUserShoppingLists(authStore.userid)
      const alreadyGenerated = Object.values(existingLists || {}).some((list) => {
        if (!list) return false
        return String(list.name || "").trim().toLowerCase() === listName.toLowerCase() && list.userGenerated === false
      })
      if (alreadyGenerated) { snack.value = { show: true, text: "Cette liste existe déjà." }; return }
      await addShoppingList(authStore.userid, { name: listName, items, userGenerated: false })
      snack.value = { show: true, text: "Liste de courses créée." }
    } catch (e) { console.error(e); errorMessage.value = "Erreur lors de la création de la liste." }
  }

  function editRecipe() {
    if (!canEditBaseRecipe.value) { errorMessage.value = "Action réservée aux administrateurs."; return }
    if (recipe.value?.baseRecipe) { router.push({ path: '/base_recipes', query: { id: recipe.value.id } }); return }
    router.push({ path: '/add_recipe', query: { id: recipe.value.id } })
  }

  function requestDelete() {
    if (!canEditBaseRecipe.value) { errorMessage.value = "Action réservée aux administrateurs."; return }
    askDelete.value = true
  }

  function toggleStore(store) {
    const list = ingEditForm.value.availableStores
    const idx = list.indexOf(store)
    if (idx === -1) list.push(store)
    else list.splice(idx, 1)
  }

  onMounted(() => {
    watch(() => authStore.userid, () => loadRecipe(), { immediate: true })
  })
  watch(sourceKey, (v) => { validPreview.value = !!v })
</script>

